export function Icon({ d, ...rest }: Omit<P, 'd'> & { d: string | string[] }) {
  return (
    <I {...rest}>
      {(Array.isArray(d) ? d : [d]).map((p) => <path key={p} d={p} />)}
    </I>
  );
}

export function AppsGlyph({ size = 20 }: { size?: number }) {
  return (
    <svg viewBox="0 0 24 24" width={size} height={size} fill="currentColor" aria-hidden="true" style={{ color: 'var(--ink-96)' }}>
      {[5.5, 12, 18.5].map((cy) => [5.5, 12, 18.5].map((cx) => <circle key={`${cx}-${cy}`} cx={cx} cy={cy} r={2.1} />))}
    </svg>
  );
}

export function MenuGlyph({ size = 19, r = 1.85 }: { size?: number; r?: number }) {
  const spread = r > 1.85 ? 7 : 6.5;
  return (
    <svg viewBox="0 0 24 24" width={size} height={size} fill="currentColor" aria-hidden="true">
      <circle cx="12" cy={12 - spread} r={r} />
      <circle cx="12" cy="12" r={r} />
      <circle cx="12" cy={12 + spread} r={r} />
    </svg>
  );
}

export function StopGlyph({ size = 15 }: { size?: number }) {
  return (
    <svg viewBox="0 0 24 24" width={size} height={size} fill="currentColor" aria-hidden="true">
      <rect x="6" y="6" width="12" height="12" rx="2.5" />
    </svg>
  );
}

export function PlayGlyph({ size = 13 }: { size?: number }) {
  return (
    <svg viewBox="0 0 24 24" width={size} height={size} fill="currentColor" style={{ marginLeft: 2 }} aria-hidden="true">
      <path d="M7.5 5.6a1 1 0 0 1 1.52-.85l9.1 5.55a1 1 0 0 1 0 1.7l-9.1 5.55a1 1 0 0 1-1.52-.85V5.6Z" />
    </svg>
  );
}

export function Spinner({ size = 15, color = 'currentColor', track = 'rgba(127,127,127,.35)', sw }: { size?: number; color?: string; track?: string; sw?: number }) {
  return (
    <span
      aria-hidden="true"
      style={{
        flex: 'none',
        display: 'block',
        boxSizing: 'border-box',
        width: size,
        height: size,
        borderRadius: '50%',
        border: `${sw ?? Math.max(1.5, Math.round(size / 9))}px solid ${track}`,
        borderTopColor: color,
        animation: 'vs-spin .75s linear infinite',
      }}
    />
  );
}

export function PauseGlyph({ size = 12 }: { size?: number }) {
  return (
    <svg viewBox="0 0 24 24" width={size} height={size} fill="currentColor" aria-hidden="true">
      <rect x="6.5" y="5" width="3.75" height="14" rx="1.2" />
      <rect x="13.75" y="5" width="3.75" height="14" rx="1.2" />
    </svg>
  );
}

export function EqBars({ bars = 4, height = 13, color = 'var(--brand)' }: { bars?: number; height?: number; color?: string }) {
  return (
    <span style={{ display: 'inline-flex', alignItems: 'flex-end', gap: 2, height }} aria-hidden="true">
      {Array.from({ length: bars }, (_, i) => (
        <span key={i} style={{ width: 2.5, height, borderRadius: 1, background: color, animation: 'vs-eq .8s ease-in-out infinite', animationDelay: `${i * 0.11}s`, transformOrigin: 'bottom' }} />
      ))}
    </span>
  );
}

export function Logo({ dark, height = 20, link = true }: { dark: boolean; height?: number; link?: boolean }) {
  const img = <img src={dark ? LOGO_DARK : LOGO_LIGHT} alt="VocalStack" decoding="sync" style={{ height, width: 'auto', display: 'block' }} />;
  return link ? <a href={SITE} style={{ display: 'block' }}>{img}</a> : img;
}

export function Mark({ dark, size = 30 }: { dark: boolean; size?: number }) {
  return <img src={dark ? MARK_DARK : MARK_LIGHT} alt="VocalStack" style={{ width: size, height: Math.round((size * 26) / 30 * 100) / 100, display: 'block' }} />;
}
